void Przedmiot::pozyskajMaterial(string login) {
    if (getStudent(login) == nullptr){
        cout << "Nie masz dostepu do przedmiotu " << nazwa << " , nie jestes przypisany do tego przedmiotu\n";
        return;
    }

    bool fromTeacher = false;

    string studentInput = "";
    cout << "Wprowadz typ materialu, ktory chcesz pozyskac - od wykladowcy lub od studentow\n";
    cout << "Wpisz jedno z nastepujacych polecen:\n";
    cout << "1)Wykladowcy\n";
    cout << "2)Studenci\n";

    cin >> studentInput;

    while (studentInput != "Wykladowcy" && studentInput != "Studenci"){
        cout << "Nieprawidlowy input, sprobuj ponownie\n";
        cin >> studentInput;
    }

    if (studentInput == "Wykladowcy"){
        fromTeacher = true;

        cout << "Lista materialow dodanych przez wykladowcow:\n";
        vector<Material*>::iterator it;
        bool atLeastOne = false;

        for (it = materialy.begin(); it != materialy.end(); it++){
            if ((*it)->getMaterialOdWykladowcy() && (*it)->getCzyJestZweryfikowany() && (*it)->getCzyJestDodanyPrzezAdmina()){
                atLeastOne = true;
                cout << (*it)->getTytul() << " ";
            }
        }

        if (!atLeastOne){
            cout << "Przedmiot o nazwie " << nazwa << " jeszcze nie ma materialow dodanych przez wykladowcow, prosze sprobowac pozniej\n";
            return;
        }
    }
    else {
        cout << "Lista materialow dodanych przez studentow:\n";
        vector<Material*>::iterator it;
        bool atLeastOne = false;

        for (it = materialy.begin(); it != materialy.end(); it++){
            if (!(*it)->getMaterialOdWykladowcy() && (*it)->getCzyJestZweryfikowany() && (*it)->getCzyJestDodanyPrzezAdmina()){
                atLeastOne = true;
                cout << (*it)->getTytul() << " ";
            }
        }

        if (!atLeastOne){
            cout << "Przedmiot o nazwie " << nazwa << " jeszcze nie ma materialow dodanych przez studentow, prosze sprobowac ponownie\n";
            return;
        }

    }

    cout << "\n";

    Material* foundMaterial = nullptr;
    string materialInput = "";

    while (true){
        cout << "Wpisz tytul materialu ktory chcesz pozyskac:\n";

        cin >> ws;
        getline(cin, materialInput);

        foundMaterial = getMaterialPoTytule(materialInput);

        if (foundMaterial == nullptr){
            cout << "Material o wprowadzonym tytule nie istnieje w systemie, prosze sprobowac ponownie\n";
            continue;
        }

        if (foundMaterial->getMaterialOdWykladowcy() != fromTeacher || !foundMaterial->getCzyJestZweryfikowany() ||
            !foundMaterial->getCzyJestDodanyPrzezAdmina()){
                cout << "Niezgodnosc wpisanego materialu z wybranym typem, prosze sprobowac ponownie\n";
                continue;
            }

            break;
    }

    cout << "Zalacznik do pobrania materialu: " << foundMaterial->getZalacznik() << "\n";
}

void Przedmiot::zaproponujMaterial(string tytul, string zalacznik, string login) {
    if (getStudent(login) == nullptr){
        cout << "Nie mozesz proponowac materialu do przedmiotu, do ktorego nie jestes przypisany, sprobuj ponownie\n";
        return;
    }

    Material* materialToAdd = new Material(tytul, zalacznik, false);
    attachMaterial(materialToAdd);
    materialToAdd->setCzyJestZweryfikowany(false);
    materialToAdd->setCzyJestDodanyPrzezAdmina(false);

    vector<Wykladowca*>::iterator it;

    for (it = wykladowcy.begin(); it != wykladowcy.end(); it++){
        (*it)->setLicznikMaterialowDoWeryfikacji((*it)->getLicznikMaterialowDoWeryfikacji() + 1);
    }



    cout << "Sugestia materialu zostala wyslana, prosze poczekac az wykladowca ja sprawdzi\n";
    return;
}

void Przedmiot::dodajMaterial(string t, string z, string login) {
    if (getWykladowca(login) == nullptr){
        cout << "Nie prowadzisz przedmiotu " << nazwa << " , prosze sprobowac ponownie\n";
        return;
    }


    while (t.size() > 64){
        cout << "Tytul materialu nie moze przekraczac 64 znaki, wprowadz tytul ponownie\n";
        cin >> ws;
        getline(cin, t);
    }



    string normalEnding = "";

    for (int i = z.size() - 1; i >= 0; i--) {
        if (z[i] != ' '){
            normalEnding = z[i] + normalEnding;
        }
        if (z[i] == '.'){
            break;
        }
    }

    while (normalEnding != ".pdf" && normalEnding != ".DOC" && normalEnding != ".tex" && normalEnding != ".cpp" && normalEnding != ".py" && normalEnding != ".java" && normalEnding != ".csv"
        && normalEnding != ".xlsx" && normalEnding != ".c" && normalEnding != ".jpg"){
            cout << "Format " << normalEnding << " nie jest obslugiwany, prosze wpisac nowy zalacznik\n";
            cin >> ws;
            getline(cin, z);

            normalEnding = "";
              for (int i = z.size() - 1; i >= 0; i--) {
                if (z[i] != ' '){
                    normalEnding = z[i] + normalEnding;
                }
                if (z[i] == '.'){
                    break;
                }
            }

    }

    Material* materialToAdd = new Material(t, z, true);

    materialToAdd->setCzyJestZweryfikowany(true);
    materialToAdd->setCzyJestDodanyPrzezAdmina(true);

    cout << "Material o tytule " << materialToAdd->getTytul() << " zostal dodany do systemu\n";

    attachMaterial(materialToAdd);
}

Student* Przedmiot::getStudent(string login) {
    vector<Student*>::iterator it;

    Student* studentFound = nullptr;

    for (it = studenci.begin(); it != studenci.end(); it++){
        if ((*it)->getLogin() == login){
            studentFound = (*it);

            break;
        }
    }

    return studentFound;
}

Wykladowca* Przedmiot::getWykladowca(string login) {
    vector<Wykladowca*>::iterator it;

    Wykladowca* wykladowcaFound = nullptr;

    for (it = wykladowcy.begin(); it != wykladowcy.end(); it++){
        if ((*it)->getLogin() == login){
            wykladowcaFound = (*it);

            break;
        }
    }

    return wykladowcaFound;
}

